import React, { Component } from 'react'
import Form from 'react-bootstrap/Form'
import Button from 'react-bootstrap/Button'
import Spinner from 'react-bootstrap/Spinner'
import ReactTooltip from "react-tooltip";

class LoginForm extends Component {
    
  
    handleChange = changeEvent => {
          
        ReactTooltip.hide();
        this.props.handleLoginChange(changeEvent)
        
    }
    
    handleSubmit = () => {

        this.props.handleLoginSubmit()

    }
    
    handleClick = () => {

            let checkUsernameAutofill = setInterval(() => {
         
         document.getElementById("login-sc-username").click();
         
        var autofilledUsername = document.getElementById('login-sc-username').value;
        console.log(autofilledUsername)
        if (autofilledUsername.length > 0) {
              this.setState({ scUsername: autofilledUsername }, () => {
                    console.log(this.state);
            })
              clearInterval(checkUsernameAutofill);
        }
      }, 1000)

    }
    
    render() {
        
        const showLoginForm = this.props.showLoginForm ? {display: 'block'} : {display: 'none'}
                
        const showLoginSubmitButton = this.props.showLoginSubmitButton ? {display: 'block'} : {display: 'none'};
        const showLoginSubmitLoadingButton = this.props.showLoginSubmitLoadingButton ? {display: 'block'} : {display: 'none'};
        

        return (
          <Form style={showLoginForm}>
            <Form.Group>
                <Form.Label>Username</Form.Label>
                <Form.Control
                    data-tip="SC Username"
                    type="text"
                    id="login-sc-username"
                    ref={this.clickInput}
                    name="scUsername"
                    autoComplete="off"
                    onClick={this.handleClick}
                    value={this.props.scUsername}
                    onChange={this.handleChange} />
                    <ReactTooltip delayShow={250}/>
                    
            <Form.Label>Password</Form.Label>
                <Form.Control
                    data-tip="SC Password"
                    type="password"
                    name="scPassword"
                    id="login-sc-password"
                    value={this.props.scPassword}
                    onChange={this.handleChange} />
                    <ReactTooltip delayShow={250}/>
              
                 
             </Form.Group>
             
            <Button
                type="submit"
                value="Submit"
                disabled={!this.props.enableLoginSubmitButton}
                onClick={e => {e.preventDefault(); this.handleSubmit()}}
                style={showLoginSubmitButton}>
                Go
            </Button>
         
             
              <Button variant="primary" disabled style={showLoginSubmitLoadingButton}>
                <Spinner
                  as="span"
                  animation="grow"
                  size="sm"
                  role="status"
                  aria-hidden="true"
                />
                Loading...
              </Button>
          </Form>
          
          
        );
    }

}

export default LoginForm;
